operation.add:
if (!empty($category_info)) {
    if (!$this->document->getDescription()) {
        $cat_desc = !empty($category_info['description'])
            ? mb_substr(html_entity_decode(strip_tags($category_info['description']), ENT_QUOTES, 'UTF-8'), 0, 155)
            : $category_info['name'] . '. Купить оптом в интернет-магазине ' . $this->config->get('config_name') . '.';
        $this->document->setDescription($cat_desc);
    }
    if (empty($category_info['meta_title'])) {
        $this->document->setTitle(
            $category_info['name'] . ' купить оптом в Мелитополе | ' . $this->config->get('config_name')
        );
    }
}
